const mcq = (id, moduleId, difficulty, question, options, correctOption, answer, explanation, questionClass = 'mba_mcq') => ({
  id: `isa_zth_${id}`,
  moduleId,
  type: 'mcq',
  difficulty,
  question,
  options,
  correctOption,
  answer,
  explanation,
  questionClass,
});

const solve = (id, moduleId, difficulty, question, answer, explanation, formula = '', questionClass = 'numerical') => ({
  id: `isa_zth_${id}`,
  moduleId,
  type: 'solving',
  difficulty,
  question,
  answer,
  explanation,
  formula,
  questionClass,
});

